            referenceLanes.withUnsafeMutableBufferPointer { destination in
                unsafe highwayStoreInterleaved4I32ConstantD(a, b, c, to: destination.baseAddress!)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c))"
            )
        }
        mismatches.record()
    }

